function combos(items, prune) {
  let count = 0;
  const chosen = [];
  function explore(i) {
    if (prune && chosen.length < 2 && i > 0) return;
    if (i === items.length) {
      if (chosen.length >= 2) count++;
      return;
    }
    chosen.push(items[i]);
    explore(i + 1);
    chosen.pop();
    explore(i + 1);
  }
  explore(0);
  return count;
}
