function visitOrders(stops) {
  const results = [];
  const route = [];
  const used = new Set();
  function explore() {
    if (route.length === stops.length) {
      results.push(route.join(">"));
      return;
    }
    for (const s of stops) {
      if (used.has(s)) continue;
      used.add(s);
      route.push(s);
      explore();
      route.pop();
      used.delete(s);
    }
  }
  explore();
  return results;
}

