const prices = [4000, 1000, 2000, 5000, 3000];

function waysToSpend(prices, budget) {
  const sorted = prices.toSorted((a, b) => a - b);
  let ways = 0;
  function explore(start, left) {
    if (left === 0) {
      ways++;
      return;
    }
    for (let i = start; i < sorted.length; i++) {
      if (sorted[i] > left) break;
      explore(i + 1, left - sorted[i]);
    }
  }
  explore(0, budget);
  return ways;
}

console.log(waysToSpend(prices, 6000));

