function countQueens(n) {
  const cols = new Set();
  const down = new Set();
  const up = new Set();
  let count = 0;
  function place(row) {
    if (row === n) {
      count++;
      return;
    }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || down.has(row - c) || up.has(row + c)) continue;
      cols.add(c);
      down.add(row - c);
      up.add(row + c);
      place(row + 1);
      cols.delete(c);
      down.delete(row - c);
      up.delete(row + c);
    }
  }
  place(0);
  return count;
}

console.log([1, 2, 3, 4, 5, 6].map(countQueens).join(" "));

