const till = [[500, 1], [200, 3]];

function fewestNotes(amount) {
  let best = null;
  function explore(i, left, used) {
    if (best !== null && used >= best) return;
    if (left === 0) {
      best = used;
      return;
    }
    if (i === till.length) return;
    const [value, count] = till[i];
    for (let n = Math.min(count, Math.floor(left / value)); n >= 0; n--) {
      explore(i + 1, left - n * value, used + n);
    }
  }
  explore(0, amount, 0);
  return best;
}

console.log(fewestNotes(600), fewestNotes(900), fewestNotes(300));

