const guests = ["Ada", "Bola", "Chidi"];
const clash = (a, b) => (a === "Ada" && b === "Bola") || (a === "Bola" && b === "Ada");
const valid = [];
const row = [];
function seat() {
  if (row.length === guests.length) {
    valid.push(row.map((g) => g[0]).join(""));
    return;
  }
  for (const g of guests) {
    if (row.includes(g)) continue;
    if (row.length > 0 && clash(row.at(-1), g)) continue;
    row.push(g);
    seat();
    row.pop();
  }
}
seat();
console.log(valid.join(" "));

function calls(n, k, prune) {
  let count = 0;
  function pick(start, left) {
    count++;
    if (left === 0) return;
    const last = prune ? n - left : n - 1;
    for (let i = start; i <= last; i++) pick(i + 1, left - 1);
  }
  pick(0, k);
  return count;
}
console.log(calls(5, 2, false), calls(5, 2, true));
